O fragmento de código C++, a seguir, contém a implementação da inserção de um nó em uma árvore binária.
```
...
struct noArvore {
   int dado;
   noArvore *esquerda;
   noArvore *direita;
};
noArvore *insere(noArvore *arvore, int valor) {
   if (arvore == NULL) {
      arvore = new noArvore;
      arvore->esquerda = NULL;
      arvore->direita = NULL;
      arvore->dado = valor;
   } else if(valor < arvore->dado) {
        arvore->esquerda = insere (arvore->esquerda, valor);
     }
     else {
        arvore->direita = insere (arvore->direita, valor);
     }
     return(arvore);
}
...
```
Com base no exposto, assinale a opção que apresenta o fragmento de programa para imprimir os valores
contidos nos nós, percorrendo a árvore em pré-ordem.

